import{_ as t,c as a,o,ah as p,ao as s,ap as i}from"./chunks/framework.Dq2_gudl.js";const m=JSON.parse('{"title":"它会在那里吗？——圣经里关于动物与天堂的盼望","description":"失去宠物后最深的疑问：它会在天堂吗？罗马书、以赛亚书与启示录给了我们什么盼望？","frontmatter":{"title":"它会在那里吗？——圣经里关于动物与天堂的盼望","description":"失去宠物后最深的疑问：它会在天堂吗？罗马书、以赛亚书与启示录给了我们什么盼望？"},"headers":[],"relativePath":"zh/pets-in-heaven/will-i-see-my-pet-again.md","filePath":"zh/pets-in-heaven/will-i-see-my-pet-again.md"}'),l={name:"zh/pets-in-heaven/will-i-see-my-pet-again.md"};function n(r,e,h,c,d,g){return o(),a("div",null,[...e[0]||(e[0]=[p('<div class="pl-quote"><p>「我知道自己会去天堂。我只是很想知道——它会不会也在那里等我？」</p><p class="pl-quote-soft">这是失去动物同伴的人，最常问、也最难问出口的问题。</p></div><section class="pl-section"><h2>先说一句诚实的话</h2><p>圣经没有写下「每一只宠物都会在天堂与主人重逢」这样的一节经文。任何人若把话说得太满，其实是超过了圣经所说的。</p><p>但也请不要因此觉得绝望。因为圣经所描绘的图画，比我们以为的更宽阔：神的救赎从来不只是「把一些人类的灵魂救出来」，而是<strong>整个受造界的更新</strong>——而动物，从头到尾都在那幅图画里。</p></section><section class="pl-section"><h2>一、受造之物，与我们一同等候</h2><blockquote><p><strong>罗马书 8:19-22</strong></p><p>&quot;For the earnest expectation of the creature waiteth for the manifestation of the sons of God… For we know that the whole creation groaneth and travaileth in pain together until now.&quot;</p></blockquote><p>保罗在这里说的，是一件很震撼的事：不只是人在叹息等候，<em>受造之物</em>也一同叹息、一同等候得赎。它们不是被留在救恩之外的布景，而是与我们一起望向同一个结局。</p><p>当你说「它那么善良，它不该就这样消失」，你所感受到的，和整个受造界所感受的是同一件事。圣经说，那份不甘心，最后会被回应。</p></section><section class="pl-section"><h2>二、神将要造的世界里，有动物</h2><blockquote><p><strong>以赛亚书 11:6-9</strong></p><p>&quot;The wolf also shall dwell with the lamb, and the leopard shall lie down with the kid; and the calf and the young lion and the fatling together; and a little child shall lead them.&quot;</p></blockquote><p>先知以赛亚所看见的未来，不是一个只有光与云的世界。他看见的是狼、羊羔、豹、山羊、牛犊与狮子，一个不再互相伤害、可以安然躺卧的世界。</p><p>如果神的心意只是「动物在今生用完就算了」，祂不必在应许里为它们留位置。祂留了。</p><p>而启示录在描述新天新地时也说：</p><blockquote><p><strong>启示录 21:4-5</strong></p><p>&quot;And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away. …Behold, I make all things new.&quot;</p></blockquote><p>「不再有死亡」是给整个受造界的宣告。你的它所经历的死亡，也是那将要被废去的一件事。</p></section><section class="pl-section"><h2>三、所以，我们可以盼望到什么程度？</h2><p>我们可以盼望，因为神是不撇下祂所造之物的神。我们可以盼望，因为基督的复活是新创造的初熟果子，而新创造的范围，圣经说是「一切」。我们可以盼望，因为那位创造动物、喜悦动物的神，不会忽然变得不在意它们。</p><p>至于「是不是同一只」「它记不记得我」——圣经没有给我们细节。它给我们的是一位可信的神，而细节在祂手中。这份留白不是要折磨我们，而是要我们把不能确定的事，交在那位良善的神手里。</p><p class="pl-quote-soft">如果你愿意，可以这样祷告：</p></section><div class="pl-quote"><p>「主啊，我不知道天堂的细节，但我相信祢是良善的。<br>祢创造了它，祢看顾了它的每一天，祢也看见我此刻的眼泪。<br>我把它交在祢手里——正如我把自己交在祢手里。<br>如果祢的应许里有它的位置，我为此感谢祢；<br>如果有人要替我照顾它，那个人是祢，我就放心了。阿们。」</p></div><section class="pl-section"><h2>给今天特别难过的你</h2><p>诗篇的作者说：「耶和华救护人和牲畜」（诗篇 36:6）。这句话很短，却是圣经里极少数直接把动物放进神救护范围的经文之一。</p><p>你的它属于那位「救护人和牲畜」的神。今天你所需要的，可能不是一个完整的答案，而是知道这件事：它在神手中，而神是好的。</p><p><a href="/zh/pets-in-heaven/">← 回到 Pets in Heaven</a> ｜ 下一篇：<a href="/zh/pets-in-heaven/not-one-sparrow-forgotten">连一只麻雀，祂都记得</a></p></section><div class="pl-cta"><h2>把它的名字写下来。</h2><p>把它的名字、它最喜欢的位置、你还没说出口的那句话写下来。PetLoss 是一个私密的空间，不上传、不催促，陪你慢慢整理。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">在 App Store 下载</a></div><div class="pl-bible"><h3>让圣经的话继续陪你</h3><p>文中引用的经文都出自圣经。用《彩虹圣经》随时阅读神的话、设置每日经文小组件，在想念它的日子里仍有一盏灯。</p><div class="pl-bible-shots"><figure><img src="'+s+'" alt="Rainbow Bible 圣经小组件显示 2 Timothy 2:13" loading="lazy"><figcaption>每日经文放在主屏幕</figcaption></figure><figure><img src="'+i+'" alt="Rainbow Bible App 的「天堂里的毛孩」主题，显示 Matthew 10:29-31" loading="lazy"><figcaption>切换到「天堂里的毛孩」主题读经</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">在 App Store 获取《彩虹圣经》</a></div>',9)])])}const u=t(l,[["render",n]]);export{m as __pageData,u as default};
